Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -57,6 +57,6 @@
 interactives.push({x:600,y:720,kind:'seal',id:'luto',label:'The Mourning House seal',house:'Casa do Luto',done:false});
 interactives.push({x:900,y:400,kind:'chapel',label:'Chapel door',done:false});
 // enemies prowl open streets and protect the ritual site.
 function spawnEnemy(x,y,type='stitched'){enemies.push({x,y,type,hp:type==='keeper'?5:3,r:type==='keeper'?18:14,speed:type==='keeper'?37:49,phase:rand(0,6),attack:0,flash:0,dead:false})}
-spawnEnemy(790,780);spawnEnemy(1210,680);spawnEnemy(600,535);spawnEnemy(1080,1100);spawnEnemy(1370,570);spawnEnemy(870,360,'keeper');
+spawnEnemy(790,780);spawnEnemy(1210,680);spawnEnemy(600,535);spawnEnemy(1080,1100);spawnEnemy(1370,570);spawnEnemy(870,360,'keeper');enemies[enemies.length-1].dormant=true;
 let noteModal=null,endingChoice=null,endingTimer=0;

input.newString:
let noteModal=null,endingChoice=null,endingTimer=0;

function sx(x){return x-camera.x}function sy(y){return y-camera.y}
function rr(x,y,w,h,r,fill){ctx.fillStyle=fill;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function text(str,x,y,size=12,color='#d7d2c3',align='left',font='IBM Plex Mono'){ctx.fillStyle=color;ctx.font=`${size}px '${font}', monospace`;ctx.textAlign=align;ctx.fillText(str,x,y)}
function drawGround(){
 ctx.fillStyle='#252a26';ctx.fillRect(0,0,W,H);
 // worn stone street tiles, deterministic grit
 for(let y=Math.floor(camera.y/64)*64;y<camera.y+H+64;y+=64)for(let x=Math.floor(camera.x/64)*64;x<camera.x+W+64;x+=64){let n=((x*7+y*13)%17+17)%17;ctx.fillStyle=n<3?'#292e29':n<6?'#272c28':'#252a26';ctx.fillRect(sx(x),sy(y),63,63);ctx.fillStyle='#30342d';ctx.fillRect(sx(x)+3,sy(y)+3,1,1);if(n===1){ctx.fillStyle='#3a302b';ctx.fillRect(sx(x)+38,sy(y)+21,5,1)}}
 // central wet road
 ctx.fillStyle='#202725';ctx.fillRect(sx(70),sy(480),1660,185);ctx.fillRect(sx(750),sy(70),300,1180);
 ctx.fillStyle='#353b36';for(let x=90;x<1720;x+=130){ctx.fillRect(sx(x),sy(569),48,2)}
 // puddles
 for(const p of [{x:755,y:520,w:55,h:20},{x:1040,y:770,w:85,h:23},{x:840,y:1160,w:95,h:30},{x:610,y:500,w:45,h:15}]){ctx.fillStyle='#3c4946';ctx.beginPath();ctx.ellipse(sx(p.x),sy(p.y),p.w,p.h,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#596762';ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(sx(p.x),sy(p.y),p.w*.65,p.h*.45,0,0,Math.PI*2);ctx.stroke()}
}
function drawBuildings(){
 for(const b of buildings){let x=sx(b.x),y=sy(b.y);if(x+b.w<-40||x>W+40||y+b.h<-50||y>H+50)continue;
 ctx.fillStyle='#141817';ctx.fillRect(x+13,y+15,b.w,b.h);ctx.fillStyle='#353b36';ctx.fillRect(x,y+9,b.w,b.h);ctx.fillStyle=b.color;ctx.fillRect(x,y,b.w,b.h);
 // flat, stepped roofs and distressed trim
 ctx.fillStyle='#606056';ctx.fillRect(x-5,y-6,b.w+10,9);ctx.fillStyle='#303532';ctx.fillRect(x+10,y+13,b.w-20,b.h-24);
 ctx.strokeStyle='#777364';ctx.lineWidth=2;ctx.strokeRect(x+2,y+2,b.w-4,b.h-4);
 for(let wx=26;wx<b.w-20;wx+=76){ctx.fillStyle='#182321';ctx.fillRect(x+wx,y+38,26,34);ctx.fillStyle='#555447';ctx.fillRect(x+wx-3,y+35,32,4);ctx.fillStyle='#a18a62';ctx.fillRect(x+wx+12,y+42,2,24)}
 ctx.fillStyle='#40352f';ctx.fillRect(x+b.w/2-29,y+b.h-55,58,50);ctx.fillStyle='#171d1c';ctx.fillRect(x+b.w/2-23,y+b.h-49,46,43);
 text(b.detail,x+b.w/2,y+24,10,'#b3aa92','center');
 }
 // buildings' hanging signs and thread banners
 for(const [x,y,label] of [[360,427,'PLANTÃO'],[1340,457,'ATELIÊ'],[360,1078,'LUTO']]){ctx.fillStyle='#201e1a';ctx.fillRect(sx(x-40),sy(y),80,22);ctx.strokeStyle='#89765c';ctx.strokeRect(sx(x-40),sy(y),80,22);text(label,sx(x),sy(y+15),9,'#c7b99d','center')}
}
function drawProps(){for(const p of props){const x=sx(p.x),y=sy(p.y);if(p.type==='car'){ctx.save();ctx.translate(x,y);ctx.rotate(p.a);ctx.fillStyle='#171c1b';ctx.fillRect(-42, -20,84,40);ctx.fillStyle='#46504b';ctx.fillRect(-36,-17,72,34);ctx.fillStyle='#252e2c';ctx.fillRect(-23,-14,46,28);ctx.fillStyle='#a27d55';ctx.fillRect(-37,-13,4,8);ctx.fillRect(33,6,4,8);ctx.restore()}
 else if(p.type==='lamp'){ctx.fillStyle='#111615';ctx.fillRect(x-2,y-14,4,29);ctx.fillStyle='#c2a16b';ctx.fillRect(x-6,y-19,12,8);ctx.fillStyle='#d2b07c';ctx.globalAlpha=.13;ctx.beginPath();ctx.arc(x,y-17,39,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
 else if(p.type==='well'){ctx.fillStyle='#161b19';ctx.beginPath();ctx.ellipse(x,y,31,18,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#687064';ctx.lineWidth=5;ctx.stroke();ctx.fillStyle='#090d0d';ctx.beginPath();ctx.ellipse(x,y,18,9,0,0,Math.PI*2);ctx.fill()}
 else if(p.type==='tree'){ctx.fillStyle='#151a18';ctx.fillRect(x-5,y,10,26);ctx.fillStyle='#242c27';ctx.beginPath();ctx.arc(x,y-5,24,0,Math.PI*2);ctx.fill();ctx.fillStyle='#34392f';ctx.beginPath();ctx.arc(x-9,y-14,12,0,Math.PI*2);ctx.fill()}}
}
function drawItem(i){if(!i.active)return;let x=sx(i.x),y=sy(i.y);ctx.fillStyle=i.type==='med'?'#86a08c':'#b89a67';ctx.fillRect(x-7,y-6,14,12);ctx.fillStyle='#202522';ctx.fillRect(x-4,y-3,8,6);text(i.type==='med'?'+':'✦',x,y+3,9,'#e1d8c0','center')}
function drawInteractives(){for(const o of interactives){if(o.kind==='note'&&o.done)continue;if(o.kind==='seal'&&seals.has(o.id))continue;if(o.kind==='chapel'&&seals.size<3)continue;let x=sx(o.x),y=sy(o.y);ctx.fillStyle=o.kind==='seal'?'#a94e46':o.kind==='chapel'?'#d2b37a':'#d6c6a0';ctx.beginPath();ctx.arc(x,y,5+Math.sin(performance.now()/210)*1.5,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#e7d5b1';ctx.globalAlpha=.35;ctx.beginPath();ctx.arc(x,y,12,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1}}
function drawEnemy(e){if(e.dead||e.dormant)return;let x=sx(e.x),y=sy(e.y);ctx.fillStyle='#111413';ctx.beginPath();ctx.ellipse(x,y+10,e.r+3,7,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=e.flash>0?'#ead4bd':e.type==='keeper'?'#674039':'#62675d';ctx.fillRect(x-e.r*.65,y-e.r*.7,e.r*1.3,e.r*1.5);ctx.fillStyle='#272e2b';ctx.fillRect(x-e.r,y-e.r*.9,e.r*2,e.r*.65);ctx.fillStyle='#bd5146';ctx.fillRect(x-5,y-7,3,2);ctx.fillRect(x+3,y-7,3,2);ctx.strokeStyle='#292321';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(x-7,y+e.r*.5);ctx.lineTo(x-13,y+e.r+5);ctx.moveTo(x+7,y+e.r*.5);ctx.lineTo(x+12,y+e.r+5);ctx.stroke();if(e.type==='keeper'){ctx.strokeStyle='#a75649';ctx.lineWidth=2;for(let i=-1;i<=1;i++){ctx.beginPath();ctx.moveTo(x+i*7,y-15);ctx.lineTo(x+i*8,y+13);ctx.stroke()}}}
function drawPlayer(){let x=sx(player.x),y=sy(player.y);ctx.fillStyle='#0b0e0e';ctx.beginPath();ctx.ellipse(x,y+11,15,7,0,0,Math.PI*2);ctx.fill();ctx.save();ctx.translate(x,y);ctx.rotate(player.face);ctx.fillStyle=player.inv>0&&Math.floor(player.inv*12)%2?'#ddd':'#384547';ctx.fillRect(-10,-11,19,23);ctx.fillStyle='#b0a58e';ctx.fillRect(-7,-16,14,11);ctx.fillStyle='#222b2b';ctx.fillRect(-8,-18,16,5);ctx.fillStyle='#151b1b';ctx.fillRect(5,-3,20,5);ctx.fillStyle='#a78b63';ctx.fillRect(21,-2,7,3);ctx.restore();}

