input.newString:
function drawPlayer(){let x=sx(player.x),y=sy(player.y);ctx.fillStyle='#0b0e0e';ctx.beginPath();ctx.ellipse(x,y+11,15,7,0,0,Math.PI*2);ctx.fill();ctx.save();ctx.translate(x,y);ctx.rotate(player.face);ctx.fillStyle=player.inv>0&&Math.floor(player.inv*12)%2?'#ddd':'#384547';ctx.fillRect(-10,-11,19,23);ctx.fillStyle='#b0a58e';ctx.fillRect(-7,-16,14,11);ctx.fillStyle='#222b2b';ctx.fillRect(-8,-18,16,5);ctx.fillStyle='#151b1b';ctx.fillRect(5,-3,20,5);ctx.fillStyle='#a78b63';ctx.fillRect(21,-2,7,3);ctx.restore();}
function nearest(){let best=null,bd=70;for(const o of interactives){if(o.kind==='note'&&o.done)continue;if(o.kind==='seal'&&seals.has(o.id))continue;if(o.kind==='chapel'&&seals.size<3)continue;let d=Math.hypot(player.x-o.x,player.y-o.y);if(d<bd){bd=d;best=o}}for(const i of items)if(i.active&&Math.hypot(player.x-i.x,player.y-i.y)<bd){bd=Math.hypot(player.x-i.x,player.y-i.y);best=i}return best}
function objective(){if(seals.size<3){const names=['Casa do Plantão','Casa do Ateliê','Casa do Luto'];return `RECOVER THE HOUSE-SEALS  ·  ${3-seals.size} REMAINING`}let boss=enemies.find(e=>e.type==='keeper');if(boss&&!boss.dead)return 'STOP THE KEEPER  ·  THE CHAPEL IS OPEN';return 'ENTER THE CHAPEL  ·  PRESS E'}
function drawHUD(){
 // vignette and film scratches
 const grad=ctx.createRadialGradient(W/2,H/2,120,W/2,H/2,570);grad.addColorStop(.35,'#05080700');grad.addColorStop(1,'#030605b8');ctx.fillStyle=grad;ctx.fillRect(0,0,W,H);
 ctx.fillStyle='#090d0dce';ctx.fillRect(20,18,266,65);ctx.strokeStyle='#6c7468';ctx.strokeRect(20.5,18.5,265,64);text('S.C.O.  /  FIELD UNIT 07',33,35,9,'#a8a899');text('PORTO SERENO   ·   03:17',33,49,10,'#ddd4c2');ctx.fillStyle='#343a35';ctx.fillRect(33,59,160,8);ctx.fillStyle=player.hp>35?'#a34c43':'#d13e35';ctx.fillRect(33,59,160*player.hp/player.maxHp,8);text(`${Math.ceil(player.hp)}%`,204,67,9,'#d7cdbb');
 ctx.fillStyle='#090d0dce';ctx.fillRect(787,18,153,67);ctx.strokeStyle='#6c7468';ctx.strokeRect(787.5,18.5,152,66);text('SERVICE PISTOL',800,36,9,'#a8a899');text(`${player.ammo}  /  ${player.reserve}`,800,61,23,'#e1d7c5');text('9MM',900,61,9,'#9b9b8b');
 // mission strip
 ctx.fillStyle='#080c0bdd';ctx.fillRect(262,17,435,31);ctx.fillStyle='#a14e44';ctx.fillRect(262,17,3,31);text(objective(),278,37,10,'#d0c9b9');
 for(let i=0;i<3;i++){ctx.strokeStyle=i<seals.size?'#bd6759':'#687064';ctx.lineWidth=2;ctx.beginPath();ctx.arc(810+i*27,104,8,0,Math.PI*2);ctx.stroke();if(i<seals.size){ctx.fillStyle='#a95147';ctx.fill()}}
 // interaction prompt
 const o=nearest();if(o){let label=o.kind==='note'?'E  READ NOTE':o.kind==='seal'?`E  TAKE ${o.label.toUpperCase()}`:o.kind==='chapel'?'E  ENTER CHAPEL':o.type==='ammo'?'E  PICK UP ROUNDS':'E  TAKE FIELD DRESSING';ctx.fillStyle='#091010df';ctx.fillRect(320,474,320,29);ctx.strokeStyle='#807c69';ctx.strokeRect(320.5,474.5,319,28);text(label,480,493,10,'#e5ddcb','center')}
 text('WASD MOVE   ·   SHIFT RUN   ·   CLICK FIRE   ·   R RELOAD   ·   E INTERACT   ·   TAB MAP',480,525,9,'#a1a399','center');
 if(fieldMap)drawMap();if(noteModal)drawNote();if(endingChoice)drawEnding();
}
