function toast(msg){toastEl.textContent=msg;toastEl.classList.add('show');toastTimer=2.3}
function blocked(x,y,r){for(const b of walls){const px=clamp(x,b.x,b.x+b.w),py=clamp(y,b.y,b.y+b.h);if(Math.hypot(x-px,y-py)<r)return true}return false}
function sound(freq=110,duration=.08,type='square',vol=.025){try{const ac=sound.ac||(sound.ac=new(window.AudioContext||window.webkitAudioContext)()),o=ac.createOscillator(),g=ac.createGain();o.type=type;o.frequency.value=freq;g.gain.value=vol;g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+duration);o.connect(g);g.connect(ac.destination);o.start();o.stop(ac.currentTime+duration)}catch{}}
let fireCooldown=0;
function fire(){if(fireCooldown>0||gameState!=='play'||noteModal||endingChoice||fieldMap)return;if(player.ammo<=0){toast('CLICK.  EMPTY.  PRESS R TO RELOAD.');sound(70,.05,'triangle',.015);fireCooldown=.25;return}player.ammo--;fireCooldown=.24;const dx=Math.cos(player.face),dy=Math.sin(player.face);bullets.push({x:player.x+dx*24,y:player.y+dy*24,vx:dx*500,vy:dy*500,life:.65});screenFlash=.07;sound(100,.11,'sawtooth',.045);for(let i=0;i<3;i++)particles.push({x:player.x+dx*25,y:player.y+dy*25,vx:rand(-60,60),vy:rand(-60,60),life:.15,color:'#d4a875'})}
function interact(){if(gameState==='dead'){reset();return}if(noteModal){noteModal=null;return}if(endingChoice){if(endingChoice==='letgo'||endingChoice==='remember')finishEnding();return}if(fieldMap){fieldMap=false;return}const o=nearest();if(!o)return;
 if(o.kind==='note'){o.done=true;noteModal=o;sound(480,.04,'sine',.012)}
 else if(o.kind==='seal'){seals.add(o.id);o.done=true;sound(390,.17,'triangle',.03);toast(`${o.house.toUpperCase()} SEAL RECOVERED  ·  ${3-seals.size} REMAINING`);if(seals.size===3){const boss=enemies.find(e=>e.type==='keeper');if(boss){boss.dormant=false;boss.hp=5}toast('THE CHAPEL DOOR OPENS. SOMETHING WAKES.') }}
 else if(o.kind==='chapel'){const boss=enemies.find(e=>e.type==='keeper');if(boss&&!boss.dead){toast('THE KEEPER STILL HOLDS THE CHAPEL.');return}endingChoice='';sound(260,.5,'sine',.025)}
 else if(o.type==='ammo'){o.active=false;player.reserve+=8;toast('8 ROUNDS RECOVERED');sound(660,.07,'sine',.02)}
 else if(o.type==='med'){o.active=false;player.hp=Math.min(100,player.hp+35);toast('FIELD DRESSING  ·  +35 VITALITY');sound(520,.12,'sine',.02)}
}
function finishEnding(){gameState='won';endingTimer=0;sound(220,.8,'sine',.025);toast(endingChoice==='letgo'?'YOU LET THE THREAD GO.':'YOU CARRY HER NAME HOME.')}
function reload(){if(player.ammo<player.clip&&player.reserve>0&&!noteModal&&!endingChoice){let n=Math.min(player.clip-player.ammo,player.reserve);player.ammo+=n;player.reserve-=n;toast(`RELOADED  ·  ${player.ammo} IN MAG`);sound(180,.13,'triangle',.02)}}
function update(dt){if(gameState!=='play')return;fireCooldown=Math.max(0,fireCooldown-dt);screenFlash=Math.max(0,screenFlash-dt);player.inv=Math.max(0,player.inv-dt);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)toastEl.classList.remove('show')}
 const mx=mouse.x+camera.x,my=mouse.y+camera.y;player.face=Math.atan2(my-player.y,mx-player.x);
 if(mouse.down)fire();
 if(!noteModal&&!endingChoice&&!fieldMap){let ax=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),ay=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0),len=Math.hypot(ax,ay)||1,speed=player.speed*(keys.shift?1.55:1);if(ax||ay){player.walk+=dt*speed/20;let nx=player.x+ax/len*speed*dt,ny=player.y+ay/len*speed*dt;if(!blocked(nx,player.y,player.r))player.x=nx;if(!blocked(player.x,ny,player.r))player.y=ny}}
 // enemy movement, contact and keeper's slow thread-bolt
 for(const e of enemies){if(e.dead||e.dormant)continue;e.flash=Math.max(0,e.flash-dt);e.attack-=dt;const d=dist(e,player);if(d>e.r+player.r+4){let vx=(player.x-e.x)/(d||1),vy=(player.y-e.y)/(d||1),speed=e.speed*(d<210?.65:1);let nx=e.x+vx*speed*dt,ny=e.y+vy*speed*dt;if(!blocked(nx,e.y,e.r))e.x=nx;if(!blocked(e.x,ny,e.r))e.y=ny}
 if(d<e.r+player.r+7&&player.inv<=0){player.hp-=e.type==='keeper'?16:10;player.inv=.9;screenFlash=.18;sound(60,.12,'sawtooth',.03);toast('WOUND SUSTAINED  ·  KEEP MOVING')}
 if(e.type==='keeper'&&d<430&&e.attack<=0){e.attack=2.1;const a=Math.atan2(player.y-e.y,player.x-e.x);enemyShots.push({x:e.x,y:e.y,vx:Math.cos(a)*180,vy:Math.sin(a)*180,life:2});sound(130,.15,'triangle',.018)} }
 for(let i=bullets.length-1;i>=0;i--){const b=bullets[i];b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(b.life<=0||blocked(b.x,b.y,2)){bullets.splice(i,1);continue}let hit=false;for(const e of enemies){if(e.dead||e.dormant)continue;if(Math.hypot(b.x-e.x,b.y-e.y)<e.r+4){e.hp--;e.flash=.12;hit=true;for(let j=0;j<5;j++)particles.push({x:b.x,y:b.y,vx:rand(-50,50),vy:rand(-50,50),life:.3,color:'#9d5148'});if(e.hp<=0){e.dead=true;player.kills++;player.reserve+=e.type==='keeper'?6:2;sound(70,.2,'triangle',.03);toast(e.type==='keeper'?'THE KEEPER IS STILL.  THE CHAPEL AWAITS.':'THE STITCHED FALLS  ·  +2 ROUNDS')}break}}if(hit)bullets.splice(i,1)}
 for(let i=enemyShots.length-1;i>=0;i--){let b=enemyShots[i];b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(b.life<=0||blocked(b.x,b.y,2)){enemyShots.splice(i,1);continue}if(Math.hypot(b.x-player.x,b.y-player.y)<player.r+5){if(player.inv<=0){player.hp-=13;player.inv=.8;screenFlash=.18;toast('THE THREAD BITES')}}enemyShots.splice(i,1)}
 for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.life<=0)particles.splice(i,1)}
 if(player.hp<=0){player.hp=0;gameState='dead';toast('SIGNAL LOST');}
 camera.x=clamp(player.x-W/2,0,world.w-W);camera.y=clamp(player.y-H/2,0,world.h-H);
}
function draw(){ctx.clearRect(0,0,W,H);drawGround();drawBuildings();drawProps();for(const i of items)drawItem(i);drawInteractives();
 for(const b of bullets){ctx.fillStyle='#f0c77e';ctx.fillRect(sx(b.x)-2,sy(b.y)-2,5,4)}for(const b of enemyShots){ctx.fillStyle='#ba5144';ctx.beginPath();ctx.arc(sx(b.x),sy(b.y),5,0,Math.PI*2);ctx.fill()}
 for(const e of enemies)drawEnemy(e);drawPlayer();for(const p of particles){ctx.globalAlpha=clamp(p.life*3,0,1);ctx.fillStyle=p.color;ctx.fillRect(sx(p.x),sy(p.y),3,3)}ctx.globalAlpha=1;
 // low-contrast, shifting fog bands obscure distant streets without hiding landmarks
 ctx.fillStyle='#b8c2bd';ctx.globalAlpha=.035;ctx.fillRect(0,0,W,H);ctx.globalAlpha=1;for(let i=0;i<7;i++){const x=((i*197+performance.now()*.008)%(W+180))-90,y=(i*83+Math.sin(performance.now()*.0004+i)*32)%H;const g=ctx.createRadialGradient(x,y,0,x,y,145);g.addColorStop(0,'#b3c2bc0b');g.addColorStop(1,'#aab9b300');ctx.fillStyle=g;ctx.fillRect(x-145,y-145,290,290)}
 if(screenFlash>0){ctx.fillStyle='#ba4437';ctx.globalAlpha=screenFlash*1.8;ctx.fillRect(0,0,W,H);ctx.globalAlpha=1}drawHUD();
 if(gameState==='dead'){ctx.fillStyle='#050807d9';ctx.fillRect(0,0,W,H);text('NO ANSWER',480,218,28,'#c76b5c','center','Special Elite');text('Your name is swallowed by the fog.',480,258,14,'#d3cbbb','center','Special Elite');text('PRESS E OR ENTER TO TRY AGAIN',480,310,10,'#b1aa99','center')}
 if(gameState==='won'){ctx.fillStyle='#050807d9';ctx.fillRect(0,0,W,H);text('FIELD REPORT  ·  CLOSED',480,202,15,'#c77d68','center');text('PORTO SERENO IS QUIET. FOR NOW.',480,242,22,'#e1d7c5','center','Special Elite');text(endingChoice==='letgo'?'You left the thread at the chapel.':'You brought her name back with you.',480,279,14,'#c2bcac','center','Special Elite');text(`STITCHED DISPERSED  ${player.kills}     SEALS  ${seals.size}/3`,480,326,10,'#a6a396','center');text('PRESS ENTER TO PLAY AGAIN',480,378,10,'#b7ac99','center')}
}

